scandinavian_tasks = ['BornholmBitextMining', 'DKClusteringP2P', 'DKClusteringS2S', 'NoClusteringP2P', 'NoClusteringS2S', 'SVClusteringP2P', 'SVClusteringS2S', 'DkkiBitextMining', 'NorwayEmbeddingsRetrieval', 'NorwayWebTitleQueriesRetrieval', 'NorwayWebTitleRetrieval', 'NorwayWebTitleAbstractRetrieval', 'NorwayWebTitleBodyRetrieval', 'NorwayWebTitleBodyRetrieval', 'SwedishClassification', 'SwedishSentimentClassification', 'NorwegianClassification', 'DanishClassification']

