import json
from pathlib import Path
from collections import defaultdict

# Define Scandinavian tasks - we need to find the actual task names used
scandinavian_task_patterns = [
    'Bornholm', 'DKCluster', 'NoCluster', 'SVCluster', 'Dkki',
    'Swedish', 'Danish', 'Norwegian'
]

cache_root = Path('/root/.cache/mteb/results/results')
model_scores = defaultdict(list)

# Iterate through all models and their revisions
for model_dir in sorted(cache_root.iterdir()):
    if not model_dir.is_dir():
        continue

    model_name = model_dir.name.replace('__', '/')

    # Find all revisions
    for revision_dir in model_dir.iterdir():
        if not revision_dir.is_dir():
            continue

        # Look for Scandinavian task results
        for task_file in revision_dir.glob('*.json'):
            task_name = task_file.stem

            # Check if this matches any Scandinavian task pattern
            is_scandinavian = any(pattern.lower() in task_name.lower() for pattern in scandinavian_task_patterns)

            if is_scandinavian:
                try:
                    with open(task_file) as f:
                        data = json.load(f)
                        # Extract main score from scores structure
                        if 'scores' in data and isinstance(data['scores'], dict):
                            for split, split_scores in data['scores'].items():
                                if isinstance(split_scores, list) and split_scores:
                                    score = split_scores[0].get('main_score')
                                    if score is not None:
                                        model_scores[model_name].append((task_name, float(score)))
                                        break  # Use first split only
                except Exception as e:
                    pass

# Calculate averages
model_averages = {}
for model_name, scores in model_scores.items():
    if scores:
        avg = sum(s[1] for s in scores) / len(scores)
        model_averages[model_name] = {
            'average': avg,
            'task_count': len(scores),
        }

# Sort by average score
if model_averages:
    sorted_models = sorted(model_averages.items(), key=lambda x: x[1]['average'], reverse=True)
    print('Top 15 models for Scandinavian tasks:')
    for i, (name, data) in enumerate(sorted_models[:15]):
        print(f"{i+1}. {name}: {data['average']:.4f} (from {data['task_count']} tasks)")

    best_model = sorted_models[0][0]
    print(f'\n>>> Best model: {best_model}')
else:
    print('No model scores found')
PYEOF
